const articleSections = {
  en: {
    intent:["Start with the job, not the hype","A spreadsheet is useful when it reduces research time without hiding the decisions that still belong to the buyer. Begin by writing down the category, size range, maximum item price and the two details that would make you reject an item. This prevents an attractive thumbnail from becoming the entire decision. A good directory should help you discover candidates; it should never turn the word “find” into a quality guarantee. Treat every product link as the start of a verification process."],
    shortlist:["Build a small comparison set","Open three to five plausible listings instead of twenty random tabs. Record the visible price, available variants, size chart, material description, seller history shown on the source marketplace and whether useful warehouse photos exist. Remove entries with missing critical information. The goal is not to identify a universal best item. It is to find the option whose evidence matches your priorities and risk tolerance."],
    listing:["Read the current source listing","Product routes can change, variants sell out and sellers edit descriptions. Re-open the source page immediately before placing an order. Confirm the chosen color, size, version and seller notes. Screenshots can be useful for your records, but they are not a substitute for the current page. If a product name in a spreadsheet is broader than the source listing, rely on the source listing."],
    measurements:["Use measurements, not familiar labels","A tagged medium is not a standardized physical size. Compare chest width, garment length, shoulder width and sleeve length with an item you already own. For shoes, compare the insole length when available. Allow for the cut you want and possible measurement tolerance. If the listing lacks a useful chart, add that uncertainty to your decision rather than pretending it does not exist."],
    total:["Estimate total cost before judging value","The visible product price is only one layer. Add domestic shipping, service charges where applicable, optional inspection, international freight, insurance and possible customs costs. Heavy or bulky low-price items can produce an expensive parcel. Approximate USD prices in this directory are for comparison, not a final checkout quote. Recalculate against the current exchange rate and route rules before paying."],
    decision:["Keep a short decision record","Write one sentence explaining why you selected or rejected each final candidate. Note the date, variant, expected measurements and unresolved risk. When warehouse photos arrive, compare them against those notes rather than relying on memory. This small habit makes a spreadsheet a genuine research tool: it connects discovery, verification, inspection and parcel planning in one traceable sequence."],
    baseline:["Create a neutral baseline","QC photos should be judged against the ordered variant and the evidence available on the source listing, not against a vague memory of a campaign image. Put the order details, size, color and reference photos side by side. First confirm that the received item is the correct product. Then move from large structural features to small details. This order prevents a tiny logo concern from distracting you from the wrong size or a visible construction defect."],
    shoes:["Shoes: shape before stitching","Check the pair together from the front, sides, back and above. Compare toe shape, heel height, panel alignment and left/right symmetry. Then inspect stitching, edge paint, sole bonding and visible glue. Request an insole measurement if sizing is important and the supplied photos do not show it. Lighting and camera angle can distort color and proportions, so compare equivalent angles before drawing a conclusion."],
    clothing:["Clothing: measurements and construction","Start with the full front and back. Look for twisting, uneven hems, mismatched sleeves, fabric pulls and staining. Zoom into seams, embroidery and printed areas only after the structure looks correct. A ruler photo of chest width and length is usually more useful than a close-up of a neck label. If a design placement matters, compare its distance from seams rather than judging by eye alone."],
    accessories:["Accessories: hardware, edges and function","For bags, belts and small accessories, inspect overall geometry, edge finishing, stitching density, hardware color and attachment points. Ask for zippers, clasps or moving parts to be shown in a useful position. Interior photos can reveal lining, pockets and construction that exterior images hide. For electronics, visible photos cannot establish battery health, internal components or long-term reliability; understand the limits of a visual inspection."],
    extras:["Know when extra photos are worth it","Request additional evidence when a decision-critical area is missing, blurred, hidden by packaging or photographed at an unusable angle. Be specific: ask for a straight-on heel photo, a ruler across the chest, a close-up of a stain or a powered-on screen. Generic requests often produce generic images. Extra photos do not remove all risk, but they can resolve a clearly stated uncertainty."],
    twoWeights:["Understand the two weights","Actual weight is measured on a scale. Volumetric weight estimates the space a parcel occupies. Many routes compare the two and use the higher figure for pricing. That means a light but large box can cost more than its scale weight suggests. The current official estimator describes volumetric weight as length × width × height in centimeters divided by 6000, while individual routes can use different divisors or rounding rules."],
    volume:["Model the parcel, not only each item","A product estimate does not automatically equal its share of a consolidated parcel. Boxes, protective materials and empty space affect final dimensions. Use the calculator as a planning tool: enter realistic packed dimensions, compare the result with actual weight, then test how a smaller box changes the comparison. Do not present the result as a guaranteed freight quote."],
    packaging:["Packaging choices change the equation","Removing a shoe box may reduce volume, but it can also reduce protection. Vacuum packing can help soft clothing and may be unsuitable for structured garments. Reinforcement adds material and weight but may lower damage risk. Decide which items can be compressed, which need corner protection and which should remain boxed. The cheapest packing choice is not automatically the best value."],
    consolidation:["Use the storage window deliberately","The official beginner guide currently states that items receive 90 days of free storage, allowing buyers to stock and consolidate before international shipment. Consolidation can reduce repeated base charges, but waiting for many bulky items can also create a large volumetric parcel. Track arrival dates and expected dimensions instead of treating consolidation as an automatic saving."],
    route:["Compare route rules, not just one price","Check destination coverage, prohibited categories, weight limits, insurance terms, tracking level and whether billing is based on actual or volumetric weight. Seasonal congestion and customs conditions can change transit performance. A route that is cheapest for a small clothing parcel may not be suitable for electronics or a large boxed item. Use the current estimator after the final rehearsal details are available."],
    record:["Save the calculation inputs","Keep the final dimensions, measured weight, selected services, route name and quoted price with the date. If the charged amount changes after packing, this record helps identify whether the cause was a new dimension, extra protection, route rule or exchange-rate movement. Good shipping research is not predicting an exact number months ahead; it is knowing which variables can change it."],
    scope:["Define what is being reviewed","Separate the purchasing agent workflow from the independent spreadsheet and from the third-party seller. A directory helps users discover links. The source marketplace seller supplies the product. The agent handles purchasing, warehouse receipt, inspection options and international parcel submission. A review that mixes these roles cannot explain where a success or failure occurred."],
    official:["Start with verifiable service facts","The current official material describes support for links from Taobao, Weidian and 1688, warehouse quality inspection with photos, a shipping estimator and 90 days of free storage for consolidation. These facts explain the intended workflow. They do not guarantee the quality of every seller, the absence of customs issues or a fixed delivery time to every destination."],
    reviews:["Read customer reviews as patterns","A single five-star or one-star review is an anecdote. Look for repeated descriptions tied to a route, date, destination or support interaction. Separate complaints about product quality from freight price, warehouse processing, carrier tracking and customs. Recent detailed reviews are usually more actionable than old ratings without order context. Treat review platforms as one evidence source, not the final verdict."],
    cost:["Compare the complete cost","Low item prices can be offset by domestic delivery, service charges, optional extras and international freight. Review whether fee explanations are visible before payment and whether the estimator assumptions match the final parcel. A responsible comparison uses the same basket, approximate dimensions, destination and protection choices across alternatives. Without that baseline, “cheaper” is only a slogan."],
    risk:["Identify risks the workflow cannot remove","QC photos can show visible condition but not guarantee authenticity, materials, internal electronics or future durability. Insurance may have exclusions. Customs rules differ by destination and can change. Sellers can delay or reject returns. A credible review names these boundaries and encourages buyers to check current rules rather than promising a risk-free purchase."],
    verdict:["Form a conditional verdict","The useful question is not whether a service is universally good or bad. Ask whether its current tools, supported routes, inspection workflow, support expectations and total cost suit a specific order. Begin with a small, replaceable purchase, keep records and evaluate each stage separately. That produces a review grounded in evidence and personal requirements rather than borrowed certainty."],
  },
  de: {
    intent:["Mit der Aufgabe beginnen, nicht mit dem Hype","Eine Tabelle ist dann nützlich, wenn sie Recherchezeit spart, ohne Entscheidungen zu verstecken, die weiterhin beim Käufer liegen. Notiere zuerst Kategorie, Größenbereich, maximales Artikelbudget und zwei Ausschlusskriterien. So wird ein attraktives Vorschaubild nicht zur gesamten Entscheidungsgrundlage. Ein gutes Verzeichnis liefert Kandidaten; das Wort „Fund“ ist jedoch nie ein Qualitätsversprechen. Jeder Produktlink ist der Anfang einer Prüfung."],
    shortlist:["Eine kleine Vergleichsliste aufbauen","Öffne drei bis fünf plausible Angebote statt zwanzig beliebiger Tabs. Halte sichtbaren Preis, Varianten, Größentabelle, Materialangaben, erkennbare Verkäuferhistorie und vorhandene Lagerfotos fest. Streiche Einträge, bei denen entscheidende Angaben fehlen. Gesucht wird nicht der universell beste Artikel, sondern die Option, deren Belege zu deinen Prioritäten und deiner Risikobereitschaft passen."],
    listing:["Das aktuelle Quellangebot lesen","Produktwege können sich ändern, Varianten sind ausverkauft und Verkäufer bearbeiten Beschreibungen. Öffne die Quellseite unmittelbar vor der Bestellung erneut. Bestätige Farbe, Größe, Version und Verkäuferhinweise. Screenshots sind für die Dokumentation hilfreich, ersetzen aber nie die aktuelle Seite. Wenn die Bezeichnung in der Tabelle allgemeiner ist als das Angebot, gilt die Quellseite."],
    measurements:["Maße statt vertrauter Etiketten verwenden","Eine Größe M ist kein standardisiertes physisches Maß. Vergleiche Brustweite, Länge, Schulterbreite und Ärmellänge mit einem passenden Kleidungsstück, das du besitzt. Bei Schuhen ist die Innensohlenlänge hilfreich. Berücksichtige gewünschten Schnitt und Messtoleranzen. Fehlt eine brauchbare Tabelle, behandle das als Unsicherheit, statt sie zu ignorieren."],
    total:["Gesamtkosten vor dem Werturteil schätzen","Der sichtbare Artikelpreis ist nur eine Ebene. Rechne Inlandsversand, mögliche Servicegebühren, optionale Kontrolle, internationalen Versand, Versicherung und mögliche Zollkosten hinzu. Schwere oder sperrige Billigartikel können ein teures Paket verursachen. Die USD-Werte dieses Verzeichnisses dienen dem Vergleich und sind kein Endpreis. Prüfe Wechselkurs und aktuelle Routenregeln vor der Zahlung erneut."],
    decision:["Eine kurze Entscheidungsspur führen","Notiere in einem Satz, warum du jeden finalen Kandidaten ausgewählt oder verworfen hast. Ergänze Datum, Variante, erwartete Maße und offenes Risiko. Vergleiche eingehende Lagerfotos mit diesen Notizen statt mit deiner Erinnerung. So verbindet die Tabelle Entdeckung, Prüfung, Inspektion und Paketplanung in einer nachvollziehbaren Reihenfolge."],
    baseline:["Eine neutrale Ausgangsbasis schaffen","QC-Fotos sollten mit der bestellten Variante und den Belegen des Quellangebots verglichen werden, nicht mit einer vagen Erinnerung an ein Werbebild. Lege Bestelldaten, Größe, Farbe und Referenzbilder nebeneinander. Bestätige zuerst den richtigen Artikel und prüfe danach von großen Strukturen zu kleinen Details. So lenkt ein kleines Logoproblem nicht von einer falschen Größe oder einem Konstruktionsfehler ab."],
    shoes:["Schuhe: zuerst die Form, dann die Nähte","Prüfe das Paar gemeinsam von vorn, seitlich, hinten und oben. Vergleiche Zehenform, Absatzhöhe, Panel-Ausrichtung und Links-rechts-Symmetrie. Danach folgen Nähte, Kantenfarbe, Sohlenverklebung und sichtbarer Kleber. Ist die Passform wichtig, fordere bei Bedarf ein Innensohlenmaß an. Licht und Kamerawinkel verzerren Farbe und Proportionen; vergleiche deshalb ähnliche Perspektiven."],
    clothing:["Kleidung: Maße und Konstruktion","Beginne mit Vorder- und Rückansicht. Achte auf Verdrehungen, ungleichmäßige Säume, unterschiedliche Ärmel, gezogene Fäden und Flecken. Vergrößere Nähte, Stickerei und Druck erst, wenn die Grundform stimmt. Ein Linealfoto von Brustweite und Länge ist meist hilfreicher als ein Nahbild des Nackenlabels. Wichtige Motivpositionen sollten anhand ihrer Abstände zu Nähten beurteilt werden."],
    accessories:["Accessoires: Beschläge, Kanten und Funktion","Bei Taschen, Gürteln und kleinen Accessoires prüfst du Geometrie, Kantenfinish, Stichdichte, Metallfarbe und Befestigungspunkte. Reißverschlüsse, Verschlüsse und bewegliche Teile sollten in brauchbarer Position gezeigt werden. Innenfotos zeigen Futter, Taschen und verdeckte Konstruktion. Bei Elektronik können Fotos weder Akkuzustand noch interne Bauteile oder langfristige Zuverlässigkeit belegen."],
    extras:["Wann zusätzliche Fotos sinnvoll sind","Fordere weitere Belege an, wenn ein entscheidender Bereich fehlt, unscharf ist, von Verpackung verdeckt wird oder aus einem unbrauchbaren Winkel fotografiert wurde. Formuliere konkret: gerade Fersenansicht, Lineal über der Brust, Nahaufnahme eines Flecks oder eingeschaltetes Display. Allgemeine Anfragen liefern oft allgemeine Bilder. Zusatzfotos beseitigen nicht jedes Risiko, können aber eine klar benannte Unsicherheit klären."],
    twoWeights:["Die zwei Gewichte verstehen","Das Realgewicht wird gewogen; das Volumengewicht schätzt den beanspruchten Raum. Viele Routen vergleichen beide Werte und berechnen den höheren. Deshalb kann ein leichtes, großes Paket mehr kosten als die Waage vermuten lässt. Der aktuelle offizielle Rechner beschreibt das Volumengewicht als Länge × Breite × Höhe in Zentimetern geteilt durch 6000; einzelne Routen können andere Teiler und Rundungen nutzen."],
    volume:["Das Paket modellieren, nicht nur Einzelartikel","Eine Produktschätzung entspricht nicht automatisch seinem Anteil in einem Sammelpaket. Kartons, Schutzmaterial und Hohlräume beeinflussen die Endmaße. Nutze den Rechner zur Planung: realistische Packmaße eingeben, mit dem Realgewicht vergleichen und eine kleinere Box testen. Das Ergebnis ist eine Orientierung und keine garantierte Frachtrechnung."],
    packaging:["Verpackungsentscheidungen ändern die Rechnung","Das Entfernen eines Schuhkartons kann Volumen sparen, verringert aber eventuell den Schutz. Vakuumverpackung hilft bei weicher Kleidung und kann für strukturierte Stücke ungeeignet sein. Verstärkung erhöht Material und Gewicht, kann aber Schäden vermeiden. Entscheide bewusst, was komprimiert werden darf, was Eckschutz braucht und was im Karton bleiben sollte. Die billigste Verpackung ist nicht automatisch der beste Wert."],
    consolidation:["Das Lagerfenster bewusst nutzen","Der offizielle Einsteigerleitfaden nennt derzeit 90 Tage kostenlose Lagerung, sodass Artikel vor dem internationalen Versand gesammelt werden können. Konsolidierung kann wiederholte Grundkosten senken, doch viele sperrige Teile erzeugen möglicherweise ein großes Volumenpaket. Verfolge Eingangsdatum und erwartete Maße, statt das Sammeln automatisch als Ersparnis zu betrachten."],
    route:["Routenregeln statt nur einen Preis vergleichen","Prüfe Zielländer, verbotene Kategorien, Gewichtsgrenzen, Versicherungsbedingungen, Tracking und die Abrechnung nach Real- oder Volumengewicht. Saisonale Auslastung und Zollbedingungen verändern Laufzeiten. Die günstigste Route für ein kleines Kleidungspaket eignet sich nicht zwingend für Elektronik oder große Kartons. Nutze den aktuellen Rechner, sobald die endgültigen Paketdaten vorliegen."],
    record:["Berechnungsgrundlagen speichern","Bewahre Endmaße, gemessenes Gewicht, Zusatzdienste, Routenname und Preis mit Datum auf. Ändert sich der Betrag nach dem Packen, lässt sich erkennen, ob neue Maße, zusätzlicher Schutz, eine Routenregel oder der Wechselkurs die Ursache waren. Gute Versandplanung sagt keinen exakten Preis Monate im Voraus voraus; sie kennt die veränderlichen Größen."],
    scope:["Festlegen, was bewertet wird","Trenne Einkaufsagent, unabhängige Tabelle und Drittanbieter. Das Verzeichnis hilft bei der Linksuche, der Marktplatzverkäufer liefert den Artikel, und der Agent übernimmt Einkauf, Wareneingang, Prüfoptionen und internationalen Paketauftrag. Eine Bewertung, die diese Rollen vermischt, kann nicht erklären, an welcher Stelle Erfolg oder Problem entstanden ist."],
    official:["Mit überprüfbaren Servicefakten beginnen","Die aktuellen offiziellen Hinweise nennen Unterstützung für Taobao-, Weidian- und 1688-Links, Qualitätskontrolle mit Lagerfotos, einen Versandrechner und 90 Tage kostenlose Lagerung zur Konsolidierung. Das beschreibt den vorgesehenen Ablauf. Es garantiert weder die Qualität jedes Verkäufers noch zollfreie Zustellung oder feste Laufzeiten für jedes Ziel."],
    reviews:["Kundenbewertungen als Muster lesen","Eine einzelne Fünf- oder Ein-Stern-Bewertung ist eine Anekdote. Suche nach wiederkehrenden Schilderungen mit Route, Datum, Ziel oder Supportkontakt. Trenne Produktqualität von Frachtpreis, Lagerbearbeitung, Tracking und Zoll. Aktuelle, detaillierte Berichte sind meist hilfreicher als alte Bewertungen ohne Bestellkontext. Bewertungsplattformen sind eine Quelle, nicht das Endurteil."],
    cost:["Die vollständigen Kosten vergleichen","Niedrige Artikelpreise können durch Inlandsversand, Service, Optionen und internationale Fracht ausgeglichen werden. Prüfe, ob Gebühren vor der Zahlung verständlich sind und ob die Rechnerannahmen zum Endpaket passen. Ein fairer Vergleich verwendet denselben Warenkorb, ähnliche Maße, dasselbe Ziel und gleiche Schutzoptionen. Ohne diese Basis bleibt „günstiger“ nur ein Slogan."],
    risk:["Risiken benennen, die der Ablauf nicht entfernt","QC-Fotos zeigen den sichtbaren Zustand, garantieren aber weder Authentizität, Material, interne Elektronik noch Haltbarkeit. Versicherungen können Ausschlüsse haben. Zollregeln unterscheiden sich und ändern sich. Verkäufer können Rückgaben verzögern oder ablehnen. Eine glaubwürdige Bewertung nennt diese Grenzen und verweist auf aktuelle Regeln, statt Risikofreiheit zu versprechen."],
    verdict:["Ein bedingtes Urteil bilden","Die hilfreiche Frage lautet nicht, ob ein Service allgemein gut oder schlecht ist. Prüfe, ob Werkzeuge, Routen, Inspektionsablauf, Supporterwartung und Gesamtkosten zu einer konkreten Bestellung passen. Beginne mit einem kleinen, ersetzbaren Kauf, führe Aufzeichnungen und bewerte jede Stufe getrennt. So entsteht ein Urteil aus Belegen und eigenen Anforderungen statt aus geliehener Gewissheit."],
  },
  es: {
    intent:["Empieza por la tarea, no por la promoción","Un spreadsheet es útil cuando reduce el tiempo de búsqueda sin ocultar las decisiones que siguen siendo del comprador. Anota categoría, rango de talla, precio máximo y dos motivos de descarte. Así una miniatura atractiva no se convierte en toda la decisión. Un buen directorio ayuda a descubrir candidatos; la palabra «hallazgo» nunca garantiza calidad. Cada enlace inicia un proceso de verificación."],
    shortlist:["Crea un grupo pequeño para comparar","Abre entre tres y cinco fichas plausibles, no veinte pestañas al azar. Registra precio visible, variantes, tabla de tallas, material, historial del vendedor que muestre la fuente y disponibilidad de fotos de almacén. Elimina opciones sin datos críticos. No buscas el mejor artículo universal, sino la opción cuyas pruebas encajen con tus prioridades y tolerancia al riesgo."],
    listing:["Lee la ficha fuente vigente","Las rutas cambian, las variantes se agotan y los vendedores editan descripciones. Vuelve a abrir la página fuente justo antes de comprar y confirma color, talla, versión y notas. Las capturas sirven como registro, pero no sustituyen la página actual. Si el nombre del spreadsheet es más amplio que la ficha original, confía en la ficha original."],
    measurements:["Usa medidas, no etiquetas conocidas","Una talla M no es una medida física estándar. Compara pecho, largo, hombros y mangas con una prenda propia que te quede bien. Para calzado, usa la longitud de la plantilla cuando esté disponible. Considera el corte deseado y la tolerancia de medición. Si falta una tabla útil, incorpora esa incertidumbre a la decisión en lugar de ignorarla."],
    total:["Estima el coste total antes de juzgar el valor","El precio del artículo es solo una capa. Añade envío nacional, posibles cargos de servicio, inspección opcional, transporte internacional, seguro y posibles aduanas. Un producto barato, pesado o voluminoso puede crear un paquete caro. Los precios aproximados en USD de este directorio sirven para comparar, no son una cotización final. Revisa cambio y reglas antes de pagar."],
    decision:["Conserva un registro breve de la decisión","Escribe una frase sobre por qué elegiste o descartaste cada finalista. Anota fecha, variante, medidas esperadas y riesgo pendiente. Cuando lleguen las fotos de almacén, compáralas con esas notas, no con tu memoria. Este hábito convierte el spreadsheet en una herramienta trazable que une descubrimiento, verificación, inspección y planificación del paquete."],
    baseline:["Crea una referencia neutral","Las fotos QC deben compararse con la variante pedida y las pruebas de la ficha fuente, no con un recuerdo impreciso de una campaña. Coloca detalles del pedido, talla, color y referencias juntos. Confirma primero que llegó el producto correcto y avanza de la estructura general a los detalles. Así un pequeño logo no distrae de una talla errónea o un defecto visible."],
    shoes:["Calzado: primero la forma, después las costuras","Examina el par junto desde frente, laterales, talón y arriba. Compara puntera, altura del talón, alineación de paneles y simetría. Después revisa costuras, pintura de bordes, unión de la suela y pegamento visible. Pide medida de plantilla si la talla importa. La luz y el ángulo deforman color y proporciones; compara perspectivas equivalentes."],
    clothing:["Ropa: medidas y construcción","Empieza con vistas completas delantera y trasera. Busca torsión, bajos desiguales, mangas distintas, tirones y manchas. Amplía costuras, bordados y estampados solo después de aprobar la estructura. Una foto con regla sobre pecho y largo suele aportar más que un primer plano de etiqueta. Si la posición del diseño importa, mide su distancia respecto a las costuras."],
    accessories:["Accesorios: herrajes, bordes y función","En bolsos, cinturones y accesorios pequeños revisa geometría, acabado de bordes, densidad de puntada, color del metal y puntos de unión. Cremalleras, cierres y piezas móviles deben mostrarse en una posición útil. El interior revela forro, bolsillos y construcción oculta. En electrónica, una imagen no demuestra salud de batería, componentes internos ni fiabilidad futura."],
    extras:["Cuándo merece la pena pedir fotos extra","Solicita pruebas adicionales si falta una zona decisiva, está borrosa, tapada por embalaje o tomada desde un ángulo inútil. Sé concreto: talón de frente, regla cruzando el pecho, detalle de una mancha o pantalla encendida. Las peticiones genéricas suelen producir imágenes genéricas. Las fotos extra no eliminan todo riesgo, pero pueden resolver una duda claramente formulada."],
    twoWeights:["Comprende los dos pesos","El peso real se obtiene en una báscula; el volumétrico estima el espacio ocupado. Muchas rutas comparan ambos y cobran el mayor. Por eso una caja ligera y grande puede costar más de lo que sugiere la báscula. El estimador oficial actual explica el cálculo como largo × ancho × alto en centímetros ÷ 6000; cada ruta puede aplicar otro divisor o redondeo."],
    volume:["Modela el paquete, no solo cada artículo","La estimación de un producto no equivale automáticamente a su parte de un paquete consolidado. Cajas, protección y huecos cambian las dimensiones finales. Usa la calculadora para planificar: introduce medidas embaladas realistas, compáralas con el peso real y prueba una caja más pequeña. El resultado orienta; no es una tarifa garantizada."],
    packaging:["El embalaje cambia la ecuación","Quitar una caja de zapatos puede reducir volumen, pero también protección. El vacío ayuda con prendas blandas y puede dañar piezas estructuradas. El refuerzo añade material y peso, aunque reduce el riesgo de golpes. Decide qué se puede comprimir, qué necesita esquinas protegidas y qué debe conservar su caja. La opción de embalaje más barata no siempre ofrece el mejor valor."],
    consolidation:["Usa el periodo de almacén de forma deliberada","La guía oficial para principiantes indica actualmente 90 días de almacenamiento gratuito, lo que permite reunir artículos antes del envío internacional. Consolidar puede reducir cargos base repetidos, pero muchos productos voluminosos también crean un gran peso volumétrico. Registra fechas de llegada y dimensiones previstas en lugar de asumir que consolidar siempre ahorra."],
    route:["Compara reglas de ruta, no un solo precio","Revisa destinos, categorías prohibidas, límites de peso, condiciones de seguro, nivel de seguimiento y si se factura por peso real o volumétrico. La congestión estacional y las aduanas cambian el tránsito. Una ruta barata para ropa pequeña puede no servir para electrónica o cajas grandes. Usa el estimador vigente cuando tengas los datos finales del paquete."],
    record:["Guarda los datos del cálculo","Conserva dimensiones finales, peso medido, servicios, nombre de la ruta y precio con fecha. Si el importe cambia después del embalaje, podrás distinguir entre nuevas medidas, protección extra, regla de ruta o movimiento del cambio. Investigar bien el envío no significa predecir una cifra exacta con meses de antelación, sino saber qué variables pueden modificarla."],
    scope:["Define qué estás reseñando","Separa el flujo del agente de compra, el spreadsheet independiente y el vendedor externo. El directorio ayuda a descubrir enlaces; el vendedor del marketplace suministra el producto; el agente gestiona compra, recepción, opciones de inspección y envío internacional. Una reseña que mezcle estos papeles no puede explicar dónde se produjo un éxito o un fallo."],
    official:["Empieza con hechos verificables del servicio","El material oficial actual describe compatibilidad con enlaces de Taobao, Weidian y 1688, inspección de almacén con fotos, un estimador de envío y 90 días de almacenamiento gratuito para consolidar. Estos hechos explican el flujo previsto. No garantizan la calidad de todos los vendedores, ausencia de aduanas ni un plazo fijo para cualquier destino."],
    reviews:["Lee las opiniones como patrones","Una sola reseña de cinco o una estrella es una anécdota. Busca descripciones repetidas ligadas a ruta, fecha, destino o interacción con soporte. Separa calidad del producto, flete, procesamiento de almacén, seguimiento y aduanas. Las opiniones recientes con contexto suelen ser más útiles que puntuaciones antiguas sin pedido. Una plataforma de reseñas es una fuente, no el veredicto final."],
    cost:["Compara el coste completo","Un precio bajo puede quedar compensado por entrega nacional, servicio, extras y transporte internacional. Comprueba si las tasas se explican antes de pagar y si los supuestos del estimador coinciden con el paquete final. Una comparación responsable usa la misma cesta, dimensiones aproximadas, destino y protección. Sin esa referencia, «más barato» es solo un eslogan."],
    risk:["Identifica los riesgos que el flujo no elimina","Las fotos QC muestran el estado visible, pero no garantizan autenticidad, materiales, componentes internos o durabilidad. El seguro puede tener exclusiones. Las normas aduaneras cambian según destino. Los vendedores pueden retrasar o rechazar devoluciones. Una reseña creíble declara estos límites y anima a consultar reglas actuales en vez de prometer una compra sin riesgo."],
    verdict:["Formula un veredicto condicionado","La pregunta útil no es si el servicio es bueno o malo para todo el mundo. Pregunta si sus herramientas, rutas, inspección, expectativas de soporte y coste total encajan con un pedido concreto. Empieza con una compra pequeña y reemplazable, conserva registros y evalúa cada fase por separado. Así obtienes una conclusión basada en pruebas y necesidades propias."],
  },
  fr: {
    intent:["Commencer par le besoin, pas par la promotion","Un tableur est utile lorsqu’il réduit le temps de recherche sans masquer les décisions qui appartiennent encore à l’acheteur. Notez la catégorie, la plage de tailles, le prix maximal et deux motifs de refus. Ainsi, une miniature séduisante ne devient pas toute la décision. Un bon répertoire propose des candidats ; le mot « trouvaille » ne garantit jamais la qualité. Chaque lien ouvre une vérification."],
    shortlist:["Construire une petite sélection comparative","Ouvrez trois à cinq fiches plausibles, pas vingt onglets aléatoires. Relevez prix visible, variantes, guide des tailles, matière, historique vendeur affiché et disponibilité de photos d’entrepôt. Écartez les fiches privées d’informations critiques. Il ne s’agit pas de trouver un meilleur article universel, mais celui dont les preuves correspondent à vos priorités et à votre tolérance au risque."],
    listing:["Lire la fiche source actuelle","Les parcours changent, les variantes s’épuisent et les vendeurs modifient leurs descriptions. Rouvrez la page source juste avant de commander et confirmez couleur, taille, version et remarques. Les captures sont utiles comme archive, mais ne remplacent pas la fiche actuelle. Si le nom du tableur est plus général que la source, fiez-vous à la source."],
    measurements:["Utiliser des mesures, pas des étiquettes familières","Une taille M n’est pas une dimension physique standard. Comparez largeur poitrine, longueur, épaules et manches à un vêtement que vous possédez. Pour les chaussures, utilisez la longueur de semelle intérieure si elle existe. Tenez compte de la coupe et des tolérances. Sans tableau exploitable, intégrez cette incertitude à votre choix au lieu de l’ignorer."],
    total:["Estimer le coût total avant la valeur","Le prix affiché n’est qu’une couche. Ajoutez livraison nationale, frais de service éventuels, inspection optionnelle, transport international, assurance et droits possibles. Un article peu cher, lourd ou volumineux peut produire un colis coûteux. Les montants USD de ce répertoire servent à comparer et ne constituent pas un devis final. Revérifiez taux de change et règles de ligne avant paiement."],
    decision:["Garder une courte trace de décision","Écrivez une phrase expliquant chaque choix ou rejet final. Notez date, variante, mesures attendues et risque non résolu. Lorsque les photos d’entrepôt arrivent, comparez-les à ces notes plutôt qu’à votre mémoire. Cette habitude transforme le tableur en outil traçable reliant découverte, vérification, inspection et préparation du colis."],
    baseline:["Créer une référence neutre","Les photos QC se jugent par rapport à la variante commandée et aux preuves de la fiche source, non au souvenir vague d’une campagne. Placez détails de commande, taille, couleur et images de référence côte à côte. Confirmez d’abord le bon produit, puis allez des grandes structures aux petits détails. Un souci de logo ne détournera ainsi pas l’attention d’une mauvaise taille ou d’un défaut de construction."],
    shoes:["Chaussures : la forme avant les coutures","Examinez la paire ensemble de face, de côté, de dos et du dessus. Comparez bout, hauteur du talon, alignement des empiècements et symétrie. Vérifiez ensuite coutures, peinture des bords, collage de semelle et colle visible. Demandez une mesure intérieure si la pointure est critique. Éclairage et angle déforment couleur et proportions ; comparez des vues équivalentes."],
    clothing:["Vêtements : mesures et construction","Commencez par les vues complètes avant et arrière. Recherchez torsion, ourlets inégaux, manches différentes, fils tirés et taches. Zoomez sur coutures, broderies et impressions après validation de la structure. Une règle sur la poitrine et la longueur est souvent plus utile qu’un gros plan d’étiquette. Si le placement compte, mesurez sa distance aux coutures."],
    accessories:["Accessoires : pièces métalliques, bords et fonction","Pour sacs, ceintures et petits accessoires, contrôlez géométrie, finition des bords, densité des points, couleur du métal et attaches. Les fermetures et pièces mobiles doivent être montrées dans une position utile. Les vues intérieures révèlent doublure, poches et construction cachée. Pour l’électronique, une photo ne prouve ni batterie, ni composants internes, ni fiabilité future."],
    extras:["Savoir quand demander des photos supplémentaires","Demandez des preuves en plus lorsqu’une zone décisive manque, est floue, cachée par l’emballage ou photographiée sous un mauvais angle. Soyez précis : talon bien de face, règle sur la poitrine, gros plan d’une tache ou écran allumé. Les demandes vagues donnent souvent des images vagues. Les photos supplémentaires n’éliminent pas tout risque, mais peuvent résoudre une incertitude clairement formulée."],
    twoWeights:["Comprendre les deux poids","Le poids réel vient d’une balance ; le poids volumétrique estime l’espace occupé. De nombreuses lignes comparent les deux et facturent le plus élevé. Un grand carton léger peut donc coûter plus que ne le suggère sa masse. L’estimateur officiel actuel décrit le calcul longueur × largeur × hauteur en centimètres ÷ 6000 ; certaines lignes appliquent un autre diviseur ou arrondi."],
    volume:["Modéliser le colis, pas seulement chaque article","L’estimation d’un produit ne correspond pas automatiquement à sa part d’un colis consolidé. Cartons, protections et espaces vides modifient les dimensions finales. Utilisez le calculateur pour planifier : saisissez des mesures emballées réalistes, comparez avec le poids réel, puis testez un carton plus petit. Le résultat guide la décision et ne garantit pas un tarif."],
    packaging:["L’emballage change l’équation","Retirer une boîte à chaussures peut réduire le volume, mais aussi la protection. La mise sous vide convient aux vêtements souples et peut abîmer les pièces structurées. Le renfort ajoute matière et poids, mais limite certains dommages. Décidez ce qui peut être comprimé, ce qui exige une protection d’angle et ce qui doit rester en boîte. Le choix le moins cher n’est pas toujours le plus avantageux."],
    consolidation:["Utiliser volontairement la période de stockage","Le guide officiel débutant indique actuellement 90 jours de stockage gratuit, ce qui permet de réunir des articles avant l’envoi international. La consolidation peut réduire des frais de base répétés, mais beaucoup d’objets volumineux peuvent créer un poids volumétrique élevé. Suivez dates d’arrivée et dimensions prévues au lieu de considérer la consolidation comme une économie automatique."],
    route:["Comparer les règles de ligne, pas un seul prix","Vérifiez destinations, catégories interdites, limites de poids, assurance, niveau de suivi et facturation au poids réel ou volumétrique. Congestion saisonnière et douanes modifient les délais. Une ligne économique pour un petit colis textile peut être inadaptée à l’électronique ou à une grande boîte. Utilisez l’estimateur actuel lorsque les données finales sont disponibles."],
    record:["Conserver les données du calcul","Gardez dimensions finales, poids mesuré, services choisis, nom de la ligne et prix avec la date. Si le montant change après emballage, vous pourrez distinguer nouvelle dimension, protection ajoutée, règle de ligne ou mouvement du taux de change. Une bonne recherche d’expédition ne prédit pas un chiffre exact des mois à l’avance ; elle connaît les variables qui le modifient."],
    scope:["Définir ce qui est évalué","Séparez le parcours de l’agent d’achat, le tableur indépendant et le vendeur tiers. Le répertoire aide à découvrir des liens ; le vendeur de la marketplace fournit le produit ; l’agent gère achat, réception, options d’inspection et soumission du colis international. Un avis qui mélange ces rôles ne peut pas situer précisément un succès ou un problème."],
    official:["Commencer par des faits de service vérifiables","Les informations officielles actuelles indiquent la prise en charge de liens Taobao, Weidian et 1688, l’inspection en entrepôt avec photos, un estimateur de livraison et 90 jours de stockage gratuit pour consolider. Ces faits décrivent le parcours prévu. Ils ne garantissent ni tous les vendeurs, ni l’absence de douane, ni un délai fixe pour chaque destination."],
    reviews:["Lire les avis comme des tendances","Un avis isolé à cinq ou une étoile reste une anecdote. Cherchez des descriptions répétées associées à une ligne, une date, une destination ou un échange avec le support. Séparez qualité produit, prix du fret, traitement entrepôt, suivi et douane. Les récits récents et détaillés sont souvent plus exploitables que d’anciennes notes sans contexte. Une plateforme d’avis est une source, pas le verdict."],
    cost:["Comparer le coût complet","Un prix article bas peut être compensé par livraison nationale, service, options et fret international. Vérifiez si les frais sont expliqués avant paiement et si les hypothèses du calculateur correspondent au colis final. Une comparaison responsable utilise le même panier, des dimensions proches, la même destination et les mêmes protections. Sans cette base, « moins cher » n’est qu’un slogan."],
    risk:["Identifier les risques que le parcours ne supprime pas","Les photos QC montrent l’état visible, mais ne garantissent ni authenticité, ni matériaux, ni électronique interne, ni durabilité. L’assurance peut comporter des exclusions. Les règles douanières varient et changent. Les vendeurs peuvent retarder ou refuser un retour. Un avis crédible expose ces limites et invite à vérifier les règles actuelles au lieu de promettre un achat sans risque."],
    verdict:["Former un verdict conditionnel","La bonne question n’est pas de savoir si un service est universellement bon ou mauvais. Demandez si ses outils, lignes, inspection, niveau de support et coût total conviennent à une commande précise. Commencez par un achat petit et remplaçable, conservez les preuves et évaluez chaque étape séparément. La conclusion repose alors sur des faits et vos exigences personnelles."],
  },
  it: {
    intent:["Parti dall’obiettivo, non dalla promozione","Un foglio è utile quando riduce il tempo di ricerca senza nascondere le decisioni che restano al compratore. Scrivi categoria, intervallo taglie, prezzo massimo e due motivi di esclusione. Così una miniatura attraente non diventa l’intera decisione. Una buona directory aiuta a scoprire candidati; la parola «selezione» non garantisce qualità. Ogni link avvia una verifica."],
    shortlist:["Crea un piccolo gruppo di confronto","Apri da tre a cinque schede plausibili invece di venti tab casuali. Registra prezzo visibile, varianti, tabella taglie, materiale, storico venditore mostrato dalla fonte ed eventuali foto di magazzino. Elimina le opzioni prive di dati critici. Non cerchi il miglior articolo universale, ma quello le cui prove corrispondono alle tue priorità e alla tua tolleranza al rischio."],
    listing:["Leggi la scheda sorgente attuale","I percorsi cambiano, le varianti finiscono e i venditori modificano le descrizioni. Riapri la pagina sorgente subito prima dell’ordine e conferma colore, taglia, versione e note. Gli screenshot sono utili per l’archivio, ma non sostituiscono la pagina corrente. Se il nome nel foglio è più generico della scheda originale, fai riferimento alla scheda originale."],
    measurements:["Usa le misure, non le etichette familiari","Una taglia M non è una misura fisica standard. Confronta larghezza del petto, lunghezza, spalle e maniche con un capo che possiedi. Per le scarpe usa la lunghezza della soletta, quando disponibile. Considera vestibilità desiderata e tolleranze. Se manca una tabella utile, includi questa incertezza nella decisione invece di fingere che non esista."],
    total:["Stima il costo totale prima del valore","Il prezzo visibile è solo un livello. Aggiungi spedizione nazionale, eventuale servizio, controllo opzionale, trasporto internazionale, assicurazione e possibili dazi. Un articolo economico, pesante o ingombrante può creare un pacco costoso. I prezzi USD approssimativi della directory servono al confronto e non sono un preventivo finale. Ricontrolla cambio e regole prima del pagamento."],
    decision:["Conserva una breve traccia della decisione","Scrivi una frase sul motivo per cui hai scelto o escluso ogni finalista. Annota data, variante, misure previste e rischio irrisolto. Quando arrivano le foto di magazzino, confrontale con queste note, non con la memoria. Questa abitudine rende il foglio uno strumento tracciabile che unisce scoperta, verifica, ispezione e pianificazione del pacco."],
    baseline:["Crea un riferimento neutro","Le foto QC vanno confrontate con la variante ordinata e con le prove della scheda sorgente, non con un ricordo vago di un’immagine pubblicitaria. Affianca dettagli ordine, taglia, colore e riferimenti. Conferma prima il prodotto corretto, poi passa dalle strutture grandi ai dettagli. Così un piccolo dubbio sul logo non distrae da una taglia errata o da un difetto visibile."],
    shoes:["Scarpe: forma prima delle cuciture","Esamina la coppia insieme da davanti, lati, dietro e sopra. Confronta punta, altezza del tallone, allineamento dei pannelli e simmetria. Poi controlla cuciture, bordi, incollaggio della suola e colla visibile. Chiedi la misura della soletta se la taglia è importante. Luce e angolo alterano colore e proporzioni; confronta inquadrature equivalenti."],
    clothing:["Abbigliamento: misure e costruzione","Parti dalle viste complete davanti e dietro. Cerca torsioni, orli irregolari, maniche diverse, fili tirati e macchie. Ingrandisci cuciture, ricami e stampe solo dopo aver approvato la struttura. Una foto con righello su petto e lunghezza è spesso più utile del dettaglio dell’etichetta. Se il posizionamento conta, misura la distanza dalle cuciture."],
    accessories:["Accessori: ferramenta, bordi e funzione","Per borse, cinture e piccoli accessori controlla geometria, finitura dei bordi, densità dei punti, colore del metallo e attacchi. Cerniere, chiusure e parti mobili devono essere mostrate in una posizione utile. Le foto interne rivelano fodera, tasche e costruzione nascosta. Nell’elettronica, le immagini non provano salute della batteria, componenti interni o affidabilità futura."],
    extras:["Quando vale la pena chiedere foto extra","Richiedi altre prove quando una zona decisiva manca, è sfocata, coperta dall’imballaggio o ripresa da un’angolazione inutile. Sii preciso: tallone frontale, righello sul petto, dettaglio di una macchia o schermo acceso. Richieste generiche producono spesso immagini generiche. Le foto extra non eliminano ogni rischio, ma possono chiarire un’incertezza ben definita."],
    twoWeights:["Comprendi i due pesi","Il peso reale viene misurato su una bilancia; quello volumetrico stima lo spazio occupato. Molte linee confrontano i due valori e addebitano il maggiore. Una scatola leggera ma grande può quindi costare più di quanto suggerisca la bilancia. Il calcolatore ufficiale attuale descrive lunghezza × larghezza × altezza in centimetri ÷ 6000; singole linee possono usare divisori o arrotondamenti diversi."],
    volume:["Modella il pacco, non solo ogni articolo","La stima di un prodotto non equivale automaticamente alla sua quota in un pacco consolidato. Scatole, protezioni e spazi vuoti cambiano le dimensioni finali. Usa il calcolatore per pianificare: inserisci misure imballate realistiche, confronta il peso reale e prova una scatola più piccola. Il risultato è una guida, non una tariffa garantita."],
    packaging:["L’imballaggio cambia l’equazione","Togliere una scatola da scarpe può ridurre il volume, ma anche la protezione. Il sottovuoto aiuta con abiti morbidi e può danneggiare capi strutturati. Il rinforzo aggiunge materiale e peso, ma può limitare i danni. Decidi cosa comprimere, cosa richiede protezione agli angoli e cosa deve restare nella scatola. L’opzione più economica non è sempre il miglior valore."],
    consolidation:["Usa consapevolmente il periodo di deposito","La guida ufficiale per principianti indica attualmente 90 giorni di deposito gratuito, permettendo di raccogliere articoli prima della spedizione internazionale. Il consolidamento può ridurre costi base ripetuti, ma molti prodotti ingombranti possono creare un alto peso volumetrico. Registra date di arrivo e dimensioni previste invece di considerare automatico il risparmio."],
    route:["Confronta le regole, non un solo prezzo","Controlla destinazioni, categorie vietate, limiti di peso, assicurazione, livello di tracciamento e fatturazione su peso reale o volumetrico. Congestione stagionale e dogana cambiano i tempi. Una linea economica per un piccolo pacco di abiti può non essere adatta a elettronica o scatole grandi. Usa il calcolatore attuale quando hai i dati finali."],
    record:["Salva i dati del calcolo","Conserva dimensioni finali, peso misurato, servizi scelti, nome linea e prezzo con la data. Se l’importo cambia dopo l’imballaggio, potrai capire se dipende da nuove misure, protezione extra, regola della linea o cambio valuta. Una buona ricerca non predice un numero esatto mesi prima; identifica le variabili che possono modificarlo."],
    scope:["Definisci cosa viene recensito","Separa il flusso dell’agente d’acquisto, il foglio indipendente e il venditore terzo. La directory aiuta a scoprire link; il venditore del marketplace fornisce il prodotto; l’agente gestisce acquisto, ricezione, opzioni di controllo e invio internazionale. Una recensione che mescola questi ruoli non può spiegare dove sia nato un successo o un problema."],
    official:["Parti da fatti di servizio verificabili","Il materiale ufficiale attuale descrive supporto per link Taobao, Weidian e 1688, controllo in magazzino con foto, calcolatore di spedizione e 90 giorni di deposito gratuito per consolidare. Questi fatti spiegano il flusso previsto. Non garantiscono qualità di ogni venditore, assenza di dogana o tempi fissi per ogni destinazione."],
    reviews:["Leggi le recensioni come schemi ricorrenti","Una singola recensione da cinque o una stella è un aneddoto. Cerca descrizioni ripetute legate a linea, data, destinazione o contatto con il supporto. Separa qualità del prodotto, prezzo del trasporto, lavorazione in magazzino, tracking e dogana. Le recensioni recenti e dettagliate sono spesso più utili di vecchi voti senza contesto. Una piattaforma è una fonte, non il verdetto."],
    cost:["Confronta il costo completo","Un prezzo articolo basso può essere compensato da consegna nazionale, servizio, extra e trasporto internazionale. Verifica se le commissioni sono chiare prima del pagamento e se le ipotesi del calcolatore corrispondono al pacco finale. Un confronto responsabile usa lo stesso carrello, dimensioni simili, destinazione e protezioni uguali. Senza questa base, «più economico» è solo uno slogan."],
    risk:["Individua i rischi che il flusso non elimina","Le foto QC mostrano la condizione visibile, ma non garantiscono autenticità, materiali, componenti interni o durata. L’assicurazione può avere esclusioni. Le regole doganali variano e cambiano. I venditori possono ritardare o rifiutare i resi. Una recensione credibile dichiara questi limiti e invita a controllare le regole attuali invece di promettere un acquisto senza rischi."],
    verdict:["Formula un giudizio condizionato","La domanda utile non è se il servizio sia universalmente buono o cattivo. Chiedi se strumenti, linee, ispezione, aspettative di supporto e costo totale sono adatti a un ordine specifico. Inizia con un acquisto piccolo e sostituibile, conserva le prove e valuta ogni fase separatamente. Otterrai così una conclusione basata su fatti e requisiti personali."],
  },
};

export function getContent(language) {
  const activeLanguage = localized[language] ? language : "en";
  const base = localized[activeLanguage];
  const faqItems = base.faqItems.map(([question, answer], index) => {
    const parity = getFaqParity(activeLanguage, index);
    return [question, parity ? `${answer} ${parity}` : answer];
  });
  return { ...base, faqItems };
}

export function getArticle(slug, language) {
  const blueprint = articleBlueprints.find((item) => item.slug === slug);
  if (!blueprint) return null;
  const activeLanguage = articleSections[language] ? language : "en";
  const research = getArticleResearch(activeLanguage, slug);
  const sections = [
    ...blueprint.topics.map((topic) => articleSections[activeLanguage][topic]),
    ...research.sections,
  ].map(([heading, body], index) => {
    const parity = getArticleParity(activeLanguage, slug, index);
    return [heading, parity ? `${body} ${parity}` : body];
  });
  return {
    ...blueprint,
    title: blueprint.title[activeLanguage],
    dek: blueprint.dek[activeLanguage],
    sections,
    sourceNote: research.sourceNote,
    visual: research.visual,
  };
}

export const routePaths = [
  "", "/spreadsheet", "/finds", "/guide", "/qc", "/shipping", "/faq", "/articles",
  ...articleBlueprints.map((article) => `/articles/${article.slug}`),
];
